INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q1.4-08', 1, 'M2', '1.4', 8, 'I', 'autocontrole', 'le coup d''envie', NULL, NULL, 0, 'likert5', 'Je suis du genre à tout plaquer pour un coup d''envie.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q1.5-C1', 1, 'M2', '1.5', 1, NULL, NULL, 'financier', NULL, NULL, 0, 'binaire_chronometre', 'Tu le reçois ce soir : 120 € sur ton compte. || Tu le reçois dans six semaines : 200 € sur ton compte.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q1.5-C2', 1, 'M2', '1.5', 2, NULL, NULL, 'matériel', NULL, NULL, 0, 'binaire_chronometre', 'Tu le commandes aujourd''hui, plein tarif, livré demain. || Tu l''attends trois semaines, à prix réduit, livraison comprise.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q1.5-C3', 1, 'M2', '1.5', 3, NULL, NULL, 'matériel', NULL, NULL, 0, 'binaire_chronometre', 'Le premier appartement correct : tu signes ce mois-ci. || Celui que tu préfères vraiment : tu patientes deux mois.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q1.5-C4', 1, 'M2', '1.5', 4, NULL, NULL, 'relationnel', NULL, NULL, 0, 'binaire_chronometre', 'Une rencontre très belle, ce week-end, sans en savoir plus. || La même personne, vue dans dix jours, après un vrai échange.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q1.5-C5', 1, 'M2', '1.5', 5, NULL, NULL, 'relationnel', NULL, NULL, 0, 'binaire_chronometre', 'Le dîner qui te réchauffe ce soir, chez quelqu''un que tu connais. || Le démarrage plus lent avec quelqu''un de neuf, à construire.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q1.5-C6', 1, 'M2', '1.5', 6, NULL, NULL, 'relationnel', NULL, NULL, 0, 'binaire_chronometre', 'Le coup de foudre qui t''emporte, tout de suite. || La rencontre qui s''installe doucement, dans quelques semaines.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
