INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q1.6-É1', 1, 'M2', '1.6', 8, NULL, NULL, NULL, NULL, NULL, 0, 'autre', 'Léa gravit une colline à 6 km/h de moyenne. À quelle vitesse doit-elle redescendre le même chemin pour que sa moyenne aller-retour atteigne 12 km/h ?', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
