INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q2.6-01', 1, 'M3', '2.6', 1, NULL, NULL, 'Carrière / ambition', NULL, NULL, 0, 'autre', 'Faire grandir ce que tu construis professionnellement. Formations, responsabilités, lancement : les années où ton travail avance fort.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q2.6-02', 1, 'M3', '2.6', 2, NULL, NULL, 'Famille / projet parental', NULL, NULL, 0, 'autre', 'Faire de la place pour un enfant — ou pour ceux qui sont là. Le temps, l''énergie et les arbitrages du quotidien tournés vers la famille.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q2.6-03', 1, 'M3', '2.6', 3, NULL, NULL, 'Liberté / aventures', NULL, NULL, 0, 'autre', 'Partir, bouger, découvrir sans tout planifier. Les années où la légèreté du sac pèse plus que le socle.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q2.6-04', 1, 'M3', '2.6', 4, NULL, NULL, 'Stabilité / sécurité', NULL, NULL, 0, 'autre', 'Bâtir un socle qui tient : épargne, logement, santé, rythmes durables. Les années où tu sécurises avant d''étendre.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q2.6-05', 1, 'M3', '2.6', 5, NULL, NULL, 'Projets personnels', NULL, NULL, 0, 'autre', 'Faire vivre ce qui est à toi : créer, courir, t''engager. Les années où tes projets personnels — créatifs, sportifs, associatifs — trouvent leur fenêtre.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
