INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q3.6-P1', 1, 'M4', '3.6', 1, NULL, NULL, 'Les intérieurs', NULL, NULL, 0, 'paire_images', '« Une vie qui se passe autour de la maison » — salon chaleureux, lumière du soir, rideaux mi-clos || « Une vie qui se passe dehors, à l''air libre » — terrasse de rue, tabourets hauts, passants', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q3.6-P2', 1, 'M4', '3.6', 2, NULL, NULL, 'Les paysages', NULL, NULL, 0, 'paire_images', '« La stabilité apaisante » — prairie close, arbre centenaire, l''eau calme || « Les horizons changeants » — crête ouverte, sentier qui part, ciel de vent', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
