INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.1-31', 1, 'M11', '8.1', 31, NULL, NULL, NULL, NULL, NULL, 0, 'double_croisee', 'Quand la vie pèse, de quoi as-tu le plus besoin : mots, silence, présence ?', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.1-32', 1, 'M11', '8.1', 32, NULL, NULL, NULL, NULL, NULL, 0, 'double_croisee', 'Quelle part de toi mérite plus de place que tu lui en donnes ?', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.1-33', 1, 'M11', '8.1', 33, NULL, NULL, NULL, NULL, NULL, 0, 'double_croisee', 'Qu''est-ce qui rend difficile, pour toi, de demander de l''aide ?', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.1-34', 1, 'M11', '8.1', 34, NULL, NULL, NULL, NULL, NULL, 0, 'double_croisee', 'Quel pardon attends-tu encore, pour toi ou pour quelqu''un ?', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.1-35', 1, 'M11', '8.1', 35, NULL, NULL, NULL, NULL, NULL, 0, 'double_croisee', 'À quoi reconnaît-on, chez toi, que tu es en confiance ?', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.1-36', 1, 'M11', '8.1', 36, NULL, NULL, NULL, NULL, NULL, 0, 'double_croisee', 'Qu''est-ce que tu aimerais qu''on te dise plus souvent ?', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.2-01', 1, 'M11', '8.2', 1, NULL, NULL, 'promesse vs opportunité', NULL, NULL, 0, 'autre', 'Tu as promis ta soirée à ta moitié. Le même soir, un ami te cède deux places pour ton groupe préféré. || A. Tu gardes ta soirée : ta promesse d''abord. || B. Tu demandes à reporter la soirée, et tu y vas.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.2-02', 1, 'M11', '8.2', 2, NULL, NULL, 'honnêteté vs tendresse', NULL, NULL, 0, 'autre', 'Ta moitié te montre un projet qui lui tient à cœur. Sur plusieurs points, tu le trouves peu solide. || A. Tu dis ce que tu vois, avec des mots posés. || B. Tu soulignes d''abord ce qui marche, le reste attend.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.2-03', 1, 'M11', '8.2', 3, NULL, NULL, 'argent partagé', NULL, NULL, 0, 'autre', 'Tu pars une semaine en voyage avec la personne que tu vois. Ton budget est nettement plus large que le sien. || A. Tu proposes de payer la part qui te semble juste. || B. Tu proposes cinquante-cinquante, chacun garde son autonomie.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.2-04', 1, 'M11', '8.2', 4, NULL, NULL, 'temps donné vs temps promis', NULL, NULL, 0, 'autre', 'Ton travail déborde depuis quelques semaines. Tu ne peux pas offrir ta présence d''aujourd''hui, seulement des projets pour après. || A. Tu nommes la période creuse, sans rien promettre. || B. Tu promets le rattrapage dès le prochain week-end.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.2-05', 1, 'M11', '8.2', 5, NULL, NULL, 'loyauté vs tolérance (un secret de l''autre)', NULL, NULL, 0, 'autre', 'Un ami proche t''avoue, en confidence, une bêtise passée de ta moitié. Rien de grave, mais tu ne le savais pas. || A. Tu gardes la confidence : la parole donnée compte. || B. Tu en parles à ta moitié, source nommée.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
INSERT INTO q_doctrine_items (code, version, monde, quete, position, orientation, carte_id, facette, paire, signal_id, is_trame, format, prompt, active, created_at) VALUES ('Q8.2-06', 1, 'M11', '8.2', 6, NULL, NULL, 'confort vs risque ensemble', NULL, NULL, 0, 'autre', 'Ta moitié te propose un nouveau départ dans une autre ville. Ta vie ici te convient, et l''idée d''ailleurs te tente aussi. || A. Tu tentes le saut, à deux. || B. Tu préfères poser le projet dans du concret d''abord.', 1, 1790121600) ON CONFLICT(code) DO UPDATE SET prompt = excluded.prompt, signal_id = excluded.signal_id, is_trame = excluded.is_trame, format = excluded.format, position = excluded.position, orientation = excluded.orientation, carte_id = excluded.carte_id, facette = excluded.facette, paire = excluded.paire;
